Graph = Dict[int, Set[int]]

def color(graph: Graph, k: int) -> Optional[Dict[int, int]]:
    order = sorted(graph, key=lambda v: -len(graph[v]))
    assignment: Dict[int, int] = {}
    def visit(i: int) -> bool:
        if i == len(order): return True
        v = order[i]
        forbidden = {assignment[u] for u in graph[v] if u in assignment}
        for c in range(k):
            if c not in forbidden:
                assignment[v] = c
                if visit(i + 1): return True
                del assignment[v]
        return False
    return dict(assignment) if visit(0) else None

def chromatic_number(graph: Graph) -> int:
    return next(k for k in range(1, len(graph) + 1) if color(graph, k) is not None)

p3 = {0: {1}, 1: {0, 2}, 2: {1}}
print("chi(P3) =", chromatic_number(p3))

from typing import Dict, List, Set
Graph = Dict[int, Set[int]]

def peo_color(graph: Graph, order: List[int], k: int) -> Dict[int, int]:
    position = {v: i for i, v in enumerate(order)}
    for v in order:
        later = [u for u in graph[v] if position[u] > position[v]]
        if any(y not in graph[x] for i, x in enumerate(later) for y in later[i + 1:]):
            raise ValueError("not a perfect elimination ordering")
    colors: Dict[int, int] = {}
    for v in reversed(order):
        forbidden = {colors[u] for u in graph[v] if u in colors}
        colors[v] = next(c for c in range(k) if c not in forbidden)
    return colors

graph = {i: set() for i in range(8)}
for i in range(7): graph[i].add(i + 1); graph[i + 1].add(i)
print(peo_color(graph, list(range(8)), 2))

